import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "../styles/articles.css";
import CommentsSection from "./CommentsSection";

function ArticlesPage() {
  const { category } = useParams();
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  const [savedArticles, setSavedArticles] = useState([]);
  const [articles, setArticles] = useState([]);
  const [expandedArticles, setExpandedArticles] = useState({});

  const [currentUser, setCurrentUser] = useState(null);
  const [loadingUser, setLoadingUser] = useState(true);

  // Завантажуємо поточного користувача
  useEffect(() => {
    if (!token) {
      setCurrentUser(null);
      setLoadingUser(false);
      return;
    }

    fetch("http://127.0.0.1:8000/api/user/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => {
        setCurrentUser({
          id: Number(data.id),
          isAdmin: data.is_staff || data.is_superuser,
          isPremium: data.is_premium || false,
        });
      })
      .catch(console.error)
      .finally(() => setLoadingUser(false));
  }, [token]);

  // Завантаження збережених статей
  useEffect(() => {
    if (!token) return;

    fetch("http://127.0.0.1:8000/api/saved/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => setSavedArticles(data.map((s) => s.article)))
      .catch(console.error);
  }, [token]);

  // Завантаження статей по категорії
  useEffect(() => {
    fetch(`http://127.0.0.1:8000/api/articles/?category=${category}`, {
      headers: {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      },
    })
      .then((res) => res.json())
      .then((data) => setArticles(data))
      .catch(console.error);
  }, [category, token]);

  const toggleComments = (articleId) => {
    setExpandedArticles((prev) => ({ ...prev, [articleId]: !prev[articleId] }));
  };

  const handleDelete = (id) => {
    if (!window.confirm("Видалити статтю?")) return;
    fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => {
        if (res.ok) setArticles((prev) => prev.filter((a) => a.id !== id));
      })
      .catch(console.error);
  };

  const toggleSave = async (articleId) => {
    if (!token) {
      alert("Увійдіть, щоб зберігати статті");
      return;
    }

    const isSaved = savedArticles.includes(articleId);

    if (isSaved) {
      const res = await fetch(`http://127.0.0.1:8000/api/saved/?article=${articleId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const saved = await res.json();
      const idToDelete = saved[0]?.id;

      if (idToDelete) {
        await fetch(`http://127.0.0.1:8000/api/saved/${idToDelete}/`, {
          method: "DELETE",
          headers: { Authorization: `Bearer ${token}` },
        });
        setSavedArticles((prev) => prev.filter((id) => id !== articleId));
      }
    } else {
      const res = await fetch("http://127.0.0.1:8000/api/saved/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ article: articleId }),
      });

      if (res.ok) {
        setSavedArticles((prev) => [...prev, articleId]);
      }
    }
  };

  // Фільтрація статей перед рендером
  const visibleArticles = articles.filter((a) => {
    if (!a.is_premium) return true; // звичайна стаття завжди видима
    if (!currentUser) return false; // преміум стаття для неавторизованого користувача невидима
    return currentUser.isAdmin || currentUser.isPremium;
  });

  if (loadingUser) return <p>Завантаження...</p>;

  return (
    <div className="articles-container">
      <h2>{category.toUpperCase()}</h2>
      {visibleArticles.length === 0 ? (
        <p>Немає статей у цій категорії.</p>
      ) : (
        <div className="articles-grid">
          {visibleArticles.map((a) => (
            <div key={a.id} className="article-card">
              {a.image && <img src={a.image} alt={a.title} className="article-image" />}
              <h3>{a.title}</h3>
              <p>{a.excerpt || (a.content?.substring(0, 120) + "...")}</p>
              <small>
                {a.category} | {new Date(a.created_at).toLocaleDateString()}
              </small>

              <button
                onClick={() => toggleSave(a.id)}
                className={`save-btn ${savedArticles.includes(a.id) ? "saved" : ""}`}
              >
                {savedArticles.includes(a.id) ? "💾 Збережено" : "📥 Зберегти"}
              </button>

              {currentUser?.isAdmin && (
                <div className="admin-controls">
                  <button onClick={() => navigate(`/edit-article/${a.id}`)}>✏️ Редагувати</button>
                  <button onClick={() => handleDelete(a.id)}>🗑️ Видалити</button>
                </div>
              )}

              <button onClick={() => toggleComments(a.id)}>
                💬 {expandedArticles[a.id] ? "Сховати коментарі" : "Показати коментарі"}
              </button>

              {expandedArticles[a.id] && (
                <CommentsSection
                  articleId={a.id}
                  token={token}
                  currentUserId={currentUser?.id || null}
                  isAdmin={currentUser?.isAdmin || false}
                />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default ArticlesPage;
